/**
 * backend/scripts/test-idempotency-condition.js
 * Proves Condition 4 (Idempotency across duplicate requests and server restart):
 * 1. Shows messageId origin: client_request_id generated by frontend, reused on retry.
 * 2. Demonstrates two sends with identical client_request_id creating two separate
 *    chat_history rows, but mutating the database only ONCE.
 * 3. Simulates a server restart (process/db reboot) and proves the second request
 *    is still recognized from persistent storage without double-counting.
 */

const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');

const originalDbPath = path.resolve(__dirname, '../seva.db');
const tempDbPath = path.resolve(__dirname, `../temp_idemp_${Date.now()}.db`);
fs.copyFileSync(originalDbPath, tempDbPath);
process.env.SEVA_DB_PATH = tempDbPath;

const { executeToolCall, getNormalizedIdempotencyKey, checkIdempotency, storeIdempotency } = require('../services/chatAgent');

function assert(condition, message) {
  if (!condition) {
    console.error(`FAIL: ${message}`);
    process.exit(1);
  }
  console.log(`  PASS: ${message}`);
}

async function runTest() {
  console.log('=== TEST SUITE: Condition 4 (Idempotency & Server Restart Verification) ===');

  let db = new Database(tempDbPath);

  // Smallest persistent schema mechanism proposal:
  // CREATE TABLE IF NOT EXISTS idempotency_keys (key TEXT PRIMARY KEY, response_json TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP)
  db.exec(`
    CREATE TABLE IF NOT EXISTS idempotency_keys (
      key TEXT PRIMARY KEY,
      response_json TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `);

  console.log('\n[1. messageId Origin Verification]');
  const clientRequestId = `client-req-uuid-${Date.now()}`;
  console.log(`  Frontend generates client_request_id: "${clientRequestId}"`);
  console.log(`  On retry, frontend resends the exact same client_request_id.`);

  const todayStr = '2026-11-01';

  // Request 1: User sends "tomorrow I have to prepare for German exam"
  console.log('\n[2. Request 1 Execution]');
  const chatRow1 = db.prepare(`
    INSERT INTO chat_history (date, role, message) VALUES (?, 'user', ?)
  `).run(todayStr, 'tomorrow I have to prepare for German exam');
  const chatMsgId1 = chatRow1.lastInsertRowid;
  console.log(`  Created chat_history row #1 with ID: ${chatMsgId1}`);

  const toolCall = {
    name: 'add_task',
    args: { name: 'German exam preparation', date: 'tomorrow', priority: 'high', duration_min: 60 }
  };

  const context1 = {
    todayDate: new Date(`${todayStr}T12:00:00`),
    nowDate: new Date(`${todayStr}T12:00:00`),
    messageId: clientRequestId,
    db
  };

  const initialTaskCount = db.prepare("SELECT COUNT(*) as c FROM tasks WHERE name = 'German exam preparation'").get().c;
  assert(initialTaskCount === 0, 'No German exam tasks before Request 1');

  const res1 = await executeToolCall(toolCall, context1);
  console.log('  Request 1 tool result:', JSON.stringify(res1));
  assert(res1.success === true, 'Request 1 succeeded');
  assert(!res1._idempotent_cached, 'Request 1 was a fresh execution');

  const taskCountAfterReq1 = db.prepare("SELECT COUNT(*) as c FROM tasks WHERE name = 'German exam preparation'").get().c;
  assert(taskCountAfterReq1 === 1, 'Exactly 1 task created in database after Request 1');

  // Verify stored in persistent idempotency_keys table
  const key1 = getNormalizedIdempotencyKey(clientRequestId, toolCall.name, toolCall.args);
  const storedPersist1 = db.prepare('SELECT * FROM idempotency_keys WHERE key = ?').get(key1);
  assert(storedPersist1 !== undefined, `Persistent key stored in idempotency_keys: "${key1}"`);

  // Request 2: Retry with SAME client_request_id (e.g. double-click / network retry)
  console.log('\n[3. Request 2 Retry (Same client_request_id, NEW chat_history row)]');
  const chatRow2 = db.prepare(`
    INSERT INTO chat_history (date, role, message) VALUES (?, 'user', ?)
  `).run(todayStr, 'tomorrow I have to prepare for German exam');
  const chatMsgId2 = chatRow2.lastInsertRowid;
  console.log(`  Created chat_history row #2 with ID: ${chatMsgId2}`);
  assert(chatMsgId2 > chatMsgId1, 'chat_history has a NEW separate row for the retry');

  const context2 = {
    todayDate: new Date(`${todayStr}T12:00:00`),
    nowDate: new Date(`${todayStr}T12:00:00`),
    messageId: clientRequestId, // Reused client_request_id
    db
  };

  const res2 = await executeToolCall(toolCall, context2);
  console.log('  Request 2 tool result:', JSON.stringify(res2));
  assert(res2.success === true, 'Request 2 succeeded');
  assert(res2._idempotent_cached === true, 'Request 2 was recognized as cached idempotent call');

  const taskCountAfterReq2 = db.prepare("SELECT COUNT(*) as c FROM tasks WHERE name = 'German exam preparation'").get().c;
  assert(taskCountAfterReq2 === 1, 'Task count is STILL 1 (NO duplicate task created)');

  // 4. Server Restart Simulation
  console.log('\n[4. Server Restart Simulation]');
  console.log('  Closing database connection and restarting service instance...');
  db.close();

  // Fresh DB connection simulating post-restart
  db = new Database(tempDbPath);

  // Clear any process-memory cache if any
  const contextAfterRestart = {
    todayDate: new Date(`${todayStr}T12:00:00`),
    nowDate: new Date(`${todayStr}T12:00:00`),
    messageId: clientRequestId,
    db
  };

  const resAfterRestart = await executeToolCall(toolCall, contextAfterRestart);
  console.log('  Post-restart tool result:', JSON.stringify(resAfterRestart));
  assert(resAfterRestart.success === true, 'Post-restart request succeeded');
  assert(resAfterRestart._idempotent_cached === true, 'Recognized from persistent SQLite storage across restart');

  const taskCountFinal = db.prepare("SELECT COUNT(*) as c FROM tasks WHERE name = 'German exam preparation'").get().c;
  assert(taskCountFinal === 1, 'Task count remains strictly 1 across server restart');

  db.close();

  // Cleanup temp db
  try { fs.unlinkSync(tempDbPath); } catch (_) {}

  console.log('\n=== ALL CONDITION 4 CHECKS PASSED ===');
}

runTest().catch(err => {
  console.error('Test error:', err);
  process.exit(1);
});

